'use client'
import { deleteEnquiryAction,replyToEnquiryAction,setEnquiryStatusAction } from '@/app/admin/enquiries/actions'
import type { AdminCapabilities } from '@/lib/admin/access'
import type { EnquiryRecord,EnquiryReplyRecord } from '@/lib/enquiries/contracts'
import { useRouter } from 'next/navigation'
import { CatalogButtonLink } from './catalog-button'
import {AdminPageHeader} from './admin-page-header'
import {CatalogFormGrid,CatalogFormMain,CatalogFormSidebar} from './catalog-layout'
import { CatalogPanel } from './catalog-panel'
import { CrudIdentity,CrudList,CrudStatus } from './crud-list'
import { FormNotice,useAdminForm } from './form-feedback'
import { SubmissionReplyForm,SubmissionStatusForm } from './submission-forms'
import { SubmissionDetails,SubmissionReplyHistory } from './submission-inbox'

import type {EnquirySummary,SubmissionPagination} from '@/lib/admin/submission-list'

export function EnquiriesList({enquiries,capabilities,pagination,counts}:{enquiries:EnquirySummary[];capabilities:AdminCapabilities;pagination:SubmissionPagination;counts:Record<string,number>}){const router=useRouter(),mutation=useAdminForm(null),result=mutation.result,busy=mutation.submitting;return <section className="catalog-admin-page"><CrudList pagination={pagination} title="Enquiries" section="Contact" icon="people" description="Review Contact and quote submissions, then reply from one inbox." notice={<FormNotice result={result}/>} busy={busy} stats={(['open','closed'] as const).map(status=>({label:status[0].toUpperCase()+status.slice(1),value:counts[status]??0,icon:'people'}))} filters={[{key:'status',label:'Status',options:['open','closed'].map(value=>({value,label:value[0].toUpperCase()+value.slice(1)}))},{key:'source',label:'Source',options:[{value:'contact',label:'Contact page'},{value:'quote',label:'Quote popup'}]}]} columns={['Contact','Company','Source','Status','Received']} empty="No enquiries yet." rows={enquiries.map(enquiry=>({id:enquiry.id,name:enquiry.name,searchText:[enquiry.name,enquiry.email,enquiry.company,enquiry.product].join(' '),filterValues:{status:enquiry.status,source:enquiry.source},viewHref:`/admin/enquiries/${enquiry.id}`,cells:[<CrudIdentity key="name" name={enquiry.name} subtitle={enquiry.email} icon="people" href={`/admin/enquiries/${enquiry.id}`}/>,enquiry.company||'—',enquiry.source==='quote'?'Quote popup':'Contact page',<CrudStatus key="status" label={enquiry.status[0].toUpperCase()+enquiry.status.slice(1)} active={enquiry.status==='open'}/>,new Date(enquiry.created_at).toLocaleDateString('en-GB')],deletion:capabilities.delete?{description:'The enquiry and its reply history will be permanently deleted.',onConfirm:async()=>{await mutation.run(()=>deleteEnquiryAction(enquiry.id));router.refresh()}}:undefined}))}/></section>}

export function EnquiryDetails({enquiry,replies,canEdit}:{enquiry:EnquiryRecord;replies:EnquiryReplyRecord[];canEdit:boolean}){
 const details=[{label:'Email',value:<a href={`mailto:${enquiry.email}`}>{enquiry.email}</a>},{label:'Phone',value:enquiry.phone?<a href={`tel:${enquiry.dial_code}${enquiry.phone}`}>{enquiry.dial_code} {enquiry.phone}</a>:'Not specified'},{label:'Company',value:enquiry.company},{label:'Job title',value:enquiry.job_title},{label:'Country',value:enquiry.country},{label:'Product',value:enquiry.product},{label:'Volume',value:enquiry.volume},{label:'Industry',value:enquiry.industry},{label:'Preferred channel',value:enquiry.channel},{label:'Source',value:enquiry.source==='quote'?'Quote popup':'Contact page'},{label:'Language',value:enquiry.locale.toUpperCase()},{label:'Received',value:<time dateTime={new Date(enquiry.created_at).toISOString()}>{new Date(enquiry.created_at).toLocaleString('en-GB')}</time>}]
 return <section className="catalog-admin-page catalog-edit-page application-detail-page"><AdminPageHeader title={enquiry.name} actions={<CatalogButtonLink href="/admin/enquiries">Back to enquiries</CatalogButtonLink>} sticky/><CatalogFormGrid><CatalogFormMain><SubmissionDetails items={details} message={enquiry.message}/><SubmissionReplyHistory replies={replies}/>{canEdit&&<CatalogPanel title="Email reply"><SubmissionReplyForm kind="enquiry" id={enquiry.id} email={enquiry.email} initialSubject="Your enquiry to Alamir Ingredients" action={replyToEnquiryAction}/></CatalogPanel>}</CatalogFormMain><CatalogFormSidebar><CatalogPanel title="Review status"><SubmissionStatusForm kind="enquiry" id={enquiry.id} initialStatus={enquiry.status} canEdit={canEdit} action={setEnquiryStatusAction}/></CatalogPanel></CatalogFormSidebar></CatalogFormGrid></section>
}
